content:
if (ubuf[i] == '\033')
                        has_escapes = 1;
                if (ubuf[i] == '\b')
                        has_backspace = 1;
        }

        /* Beware, if the data has been truncated, the final CR could have
           been followed by a LF.  If we have ms->bytes_max bytes, it indicates
           that the data might have been truncated, probably even before
           this function was called. */
        if (seen_cr && nbytes < ms->bytes_max)
                n_cr++;

        if (strcmp(type, "binary") == 0) {
                rv = 0;
                goto done;
        }
        len = file_printedlen(ms);
        if (mime) {
                if ((mime & MAGIC_MIME_TYPE) != 0) {
                        if (len) {
                                /*
                                 * Softmagic printed something, we
                                 * are either done, or we need a separator
                                 */
                                if ((ms->flags & MAGIC_CONTINUE) == 0) {
                                        rv = 1;
                                        goto done;
                                }
                                if (need_separator && file_separator(ms) == -1)
                                        goto done;
                        } else {
                                if (file_printf(ms, "text/plain") == -1)
                                        goto done;
                        }
                }
        } else {
                if (len) {
                        switch (file_replace(ms, " text$", ", ")) {
                        case 0:
                                switch (file_replace(ms, " text executable$",
                                    ", ")) {
                                case 0:
                                        if (file_printf(ms, ", ") == -1)
                                                goto done;
                                        break;
                                case -1:
                                        goto done;
                                default:
                                        executable = 1;
                                        break;
                                }
                                break;
                        case -1:
                                goto done;
                        default:
                                break;
                        }
                }

                if (file_printf(ms, "%s", code) == -1)
                        goto done;

                if (subtype) {
                        if (file_printf(ms, " %s", subtype) == -1)
                                goto done;
                }

                if (file_printf(ms, " %s", type) == -1)
                        goto done;

                if (executable)
                        if (file_printf(ms, " executable") == -1)
                                goto done;

                if (has_long_lines)
                        if (file_printf(ms, ", with very long lines (%"
                            SIZE_T_FORMAT "u)", has_long_lines) == -1)
                                goto done;

                /*
                 * Only report line terminators if we find one other than LF,
                 * or if we find none at all.
                 */
                if ((n_crlf == 0 && n_cr == 0 && n_nel == 0 && n_lf == 0) ||
                    (n_crlf != 0 || n_cr != 0 || n_nel != 0)) {
                        if (file_printf(ms, ", with") == -1)
                                goto done;

                        if (n_crlf == 0 && n_cr == 0 &&
                            n_nel == 0 && n_lf == 0) {
                                if (file_printf(ms, " no") == -1)
                                        goto done;
                        } else {
                                if (n_crlf) {
                                        if (file_printf(ms, " CRLF") == -1)
                                                goto done;
                                        if (n_cr || n_lf || n_nel)
                                                if (file_printf(ms, ",") == -1)
                                                        goto done;
                                }
                                if (n_cr) {
                                        if (file_printf(ms, " CR") == -1)
                                                goto done;
                                        if (n_lf || n_nel)
                                                if (file_printf(ms, ",") == -1)
                                                        goto done;
                                }
                                if (n_lf) {
                                        if (file_printf(ms, " LF") == -1)
                                                goto done;
                                        if (n_nel)
                                                if (file_printf(ms, ",") == -1)
                                                        goto done;
                                }
                                if (n_nel)
                                        if (file_printf(ms, " NEL") == -1)
                                                goto done;
                        }

                        if (file_printf(ms, " line terminators") == -1)
                                goto done;
                }

                if (has_escapes)
                        if (file_printf(ms, ", with escape sequences") == -1)
                                goto done;
                if (has_backspace)
                        if (file_printf(ms, ", with overstriking") == -1)
                                goto done;
        }
        rv = 1;
done:
        free(utf8_buf);

        return rv;
}

